#!/bin/bash
# DLoop
# Copyright (c) 2026-present NAVER Corp.
#
# One-epoch DLoop training of an MTP drafter (paper recipe), transformers >= 5.16:
#   qwen3.5  the built-in MTP head of Qwen3.5-9B (read from the target checkpoint),
#            TTT unroll length drawn uniformly from 3, 6, 9 (k = 3 x {1, 2, 3} stages)
#   gemma4   the official Gemma 4 12B assistant, lengths 6, 12, 18 (k = 6)
#   DATA=<jsonl regenerated by the target> bash examples/run_dloop_mtp.sh qwen3.5|gemma4 [extra args]
# Multi-node: also set NNODES, NODE_RANK, MASTER_ADDR, MASTER_PORT (and NUM_GPUS per node).
FAMILY=${1:?usage: run_dloop_mtp.sh qwen3.5|gemma4}; shift
SCRIPT_DIR=$( cd -- "$( dirname -- "${BASH_SOURCE[0]}" )" &> /dev/null && pwd )
ROOT_DIR=$(dirname "$SCRIPT_DIR")
export TORCHINDUCTOR_CACHE_DIR=${TORCHINDUCTOR_CACHE_DIR:-$ROOT_DIR/cache/compiled_kernels}
NUM_GPUS=${NUM_GPUS:-8}
if [ -n "$NNODES" ]; then
    LAUNCH="--nnodes $NNODES --node_rank $NODE_RANK --master_addr $MASTER_ADDR --master_port $MASTER_PORT"
else
    LAUNCH="--standalone"
fi
: "${DATA:?set DATA to the regenerated training jsonl (see README, Dataset Preparation)}"
case "$FAMILY" in
    qwen3.5)
        HOST_ARGS=(--target-model-path Qwen/Qwen3.5-9B --chat-template qwen3.5-instruct --ttt-length-dist 3,6,9) ;;
    gemma4)
        # --ckpt-dir must be a local directory
        ASSISTANT=$(python -c "from huggingface_hub import snapshot_download; print(snapshot_download('google/gemma-4-12B-it-assistant'))")
        HOST_ARGS=(--target-model-path google/gemma-4-12B-it --ckpt-dir "$ASSISTANT" --chat-template gemma4 --ttt-length-dist 6,12,18) ;;
    *) echo "unknown family: $FAMILY"; exit 1 ;;
esac

torchrun $LAUNCH --nproc_per_node $NUM_GPUS \
    $ROOT_DIR/scripts/train_eagle3.py \
    --mtp $FAMILY \
    "${HOST_ARGS[@]}" \
    --train-data-path "$DATA" \
    --on-the-fly-loader \
    --max-length 4096 \
    --output-dir ${OUTPUT_DIR:-$ROOT_DIR/outputs/dloop-mtp-$FAMILY} \
    --num-epochs 1 \
    --batch-size 1 \
    --learning-rate 1e-4 \
    --warmup-ratio 0.015 \
    --max-grad-norm 0.5 \
    --seed 0 \
    --attention-backend sdpa \
    --log-interval 50 \
    --save-interval 5000 \
    --report-to tensorboard \
    "$@"
